<?php
declare(strict_types=1); namespace App\Application\FinancialDistribution;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter}; use App\Models\{CommissionAccrual,PartnerStatement,PartnerStatementItem,User}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
final class PartnerStatementService { public function __construct(private AuditWriter$audit,private OutboxWriter$outbox,private DistributionEventWriter$events){}
 public function prepare(array$d,User$actor):PartnerStatement{return DB::transaction(function()use($d,$actor){if($e=PartnerStatement::where('tenant_id',$d['tenant_id'])->where('idempotency_key',$d['idempotency_key'])->first())return$e;DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))',[implode(':',[$d['tenant_id'],$d['partner_id'],$d['period_start'],$d['period_end'],$d['currency']])]);$rows=CommissionAccrual::where('tenant_id',$d['tenant_id'])->where('partner_id',$d['partner_id'])->where('currency',$d['currency'])->whereBetween('created_at',[$d['period_start'],$d['period_end'].' 23:59:59'])->lockForUpdate()->get();$earned=$rows->sum('vested_minor');$clawed=$rows->sum('clawed_back_minor');$paid=$rows->sum('paid_minor');$payload=$rows->map(fn($a)=>[$a->id,$a->vested_minor,$a->clawed_back_minor,$a->paid_minor])->values()->all();$s=PartnerStatement::create([...$d,'statement_number'=>'PST-'.now()->format('Ymd').'-'.strtoupper(Str::random(8)),'status'=>'DRAFT','opening_balance_minor'=>$d['opening_balance_minor']??0,'earned_minor'=>$earned,'clawed_back_minor'=>$clawed,'paid_minor'=>$paid,'closing_balance_minor'=>($d['opening_balance_minor']??0)+$earned-$clawed-$paid,'content_hash'=>hash('sha256',json_encode($payload,JSON_THROW_ON_ERROR)),'prepared_by'=>$actor->id]);foreach($rows as$a)PartnerStatementItem::create(['partner_statement_id'=>$s->id,'commission_accrual_id'=>$a->id,'entry_type'=>'COMMISSION','reference_type'=>'commission_accrual','reference_id'=>$a->id,'amount_minor'=>$a->vested_minor-$a->clawed_back_minor-$a->paid_minor,'currency'=>$a->currency,'occurred_at'=>$a->created_at,'metadata'=>[]]);$this->audit->record('partner_statement.prepared','partner_statement',$s->id,['closing_balance_minor'=>$s->closing_balance_minor]);return$s->load('items');});}
 public function approve(PartnerStatement$s,User$actor):PartnerStatement{return DB::transaction(function()use($s,$actor){$s=PartnerStatement::lockForUpdate()->findOrFail($s->id);if($s->status!=='DRAFT'||$s->prepared_by===$actor->id)throw ValidationException::withMessages(['statement'=>__('wave6.maker_checker')]);$s->update(['status'=>'APPROVED','approved_by'=>$actor->id,'approved_at'=>now()]);$this->events->write($s->tenant_id,'PARTNER_STATEMENT',$s->id,'DRAFT','APPROVED','APPROVED',$actor);$this->outbox->record('partner.statement.approved','partner_statement',$s->id,['statement_id'=>$s->id]);return$s->refresh();});}
 public function publish(PartnerStatement$s,User$actor):PartnerStatement{if($s->status!=='APPROVED')throw ValidationException::withMessages(['statement'=>__('wave6.statement_not_approved')]);$s->update(['status'=>'PUBLISHED','published_at'=>now()]);$this->events->write($s->tenant_id,'PARTNER_STATEMENT',$s->id,'APPROVED','PUBLISHED','PUBLISHED',$actor);return$s->refresh();}
}
